import { Component, computed, input, InputSignal, Signal } from '@angular/core';
import { TranslateModule } from '@ngx-translate/core';

/**
 * Marks the place of a text that is still being generated by AI, so the surrounding
 * content can be shown before the generation has finished.
 */
@Component({
    selector: 'es-ai-text-placeholder',
    imports: [TranslateModule],
    templateUrl: './ai-text-placeholder.component.html',
    styleUrls: ['./ai-text-placeholder.component.scss'],
})
export class AiTextPlaceholderComponent {
    // number of placeholder lines; the last of several is drawn shorter like the end of a paragraph
    lines: InputSignal<number> = input<number>(3);

    protected readonly lineIndexes: Signal<number[]> = computed((): number[] =>
        Array.from({ length: Math.max(1, this.lines()) }, (_, index: number) => index),
    );
}
